  s=s.replace('</style>','.snav a{color:#222;text-decoration:none;margin-left:16px;font-weight:600;font-size:15px}.snav a:hover,.snav a.on{color:#b38600;border-bottom:2px solid #FFC107}footer{background:#222;color:#bbb;padding:26px 20px;margin-top:30px;font-size:14px;line-height:1.6}footer .in{max-width:1100px;margin:auto;display:flex;flex-wrap:wrap;gap:20px;justify-content:space-between}footer a{color:#FFC107;text-decoration:none;margin-right:16px}</style>',1)
  s=s.replace('</body></html>',FOOT+'</body></html>',1)
